{
  "document_type": "lease",
  "lessor": "Zhonghai Trust Co., Ltd.",
  "lessee": "Shaanxi Tianren Organic Food Co., Ltd.",
  "premises_address": "16th floor of National Development Bank Tower",
  "area": null,
  "start_date": "2008-07-01",
  "end_date": "2009-06-30",
  "rent": {
    "amount": 45.00,
    "currency": "CNY",
    "period": "month"
  },
  "indexation": "none",
  "red_flags": [
    {
      "type": "sublease_permitted",
      "quote": "During the rental, Party B is not allowed to lease all or part of the premises to a third party without the written consent of Party A."
    },
    {
      "type": "tenant_break_option",
      "quote": "If Party B intends to continue to rent, it shall inform party A in written form one months in advance. After confirmation by party A, the contract can be renewed."
    },
    {
      "type": "tenant_break_option",
      "quote": "Under the same condition, Party B has the priority to continue the contract to other civil parties."
    },
    {
      "type": "tenant_break_option",
      "quote": "When the lease term comes to an end, the contract naturally terminates."
    },
    {
      "type": "tenant_break_option",
      "quote": "The lease contract comes to an end in the case of force majeure."
    },
    {
      "type": "tenant_break_option",
      "quote": "If Party B does any of the following, Party A can break the contract and has the right to take back the premises and get twice the rent as liquidated damages by the month."
    },
    {
      "type": "tenant_break_option",
      "quote": "9.2.1 Changing the use of the house without the approval of Party A, which causes damages to the house"
    },
    {
      "type": "tenant_break_option",
      "quote": "9.2.2 There is principal structural damage to the house caused by Party B."
    }
  ]
}
